/* Stationary green cover and matching destination title. */
(()=>{const root=document.documentElement,cover=document.getElementById('plain-green-cover'),key='garmonia-next-title';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let busy=false,timer=0;const sectionNames={'index.html':'Главная','':'Главная','services.html':'Услуги','about.html':'О центре','reviews.html':'Отзывы','contacts.html':'Контакты','booking.html':'Запись'};
function setTitle(title){root.setAttribute('data-transition-title',title);if(cover)cover.textContent=title}
function done(){busy=false;root.classList.remove('garmonia-cover','cover-out');root.classList.add('garmonia-ready','cover-ready')}
let title=sectionNames[location.pathname.split('/').pop()]||document.querySelector('.detail h1')?.textContent?.trim()||document.title.split(' · ')[0]||'GARMONIA';try{const p=JSON.parse(sessionStorage.getItem(key)||'null');sessionStorage.removeItem(key);if(p&&p.url===location.href&&Date.now()-p.at<120000&&p.title)title=p.title}catch(e){}setTitle(title);
if(reduced){done();return}if(!cover)requestAnimationFrame(()=>requestAnimationFrame(()=>setTimeout(()=>{if(!busy)done()},180)));else root.classList.add('garmonia-ready');
window.addEventListener('pageshow',e=>{if(e.persisted){clearTimeout(timer);done()}});
document.addEventListener('click',e=>{if(e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;const a=e.target.closest?.('a[data-transition]');if(!a||a.target||a.hasAttribute('download'))return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||!u.pathname.includes('/garmonia/'))return;if(u.pathname===location.pathname&&u.search===location.search)return;e.preventDefault();e.stopImmediatePropagation();if(busy)return;busy=true;const next=a.dataset.transition?.trim()||sectionNames[u.pathname.split('/').pop()]||a.textContent.trim()||'GARMONIA';setTitle(next);try{sessionStorage.setItem(key,JSON.stringify({title:next,url:u.href,at:Date.now()}))}catch(e){}root.classList.add('garmonia-ready','cover-ready','garmonia-cover','cover-out');timer=setTimeout(()=>location.assign(u.href),420)},true)})();
(()=>{const d=document;d.documentElement.classList.add('js');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const menu=d.querySelector('.menu'),nav=d.querySelector('.navlinks');menu?.addEventListener('click',()=>{let open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'×':'☰'});let nodes=[...d.querySelectorAll('.reveal')];if('IntersectionObserver'in window&&!reduced){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('shown');io.unobserve(e.target)}}),{threshold:.08});nodes.forEach(n=>io.observe(n))}else nodes.forEach(n=>n.classList.add('shown'));d.querySelectorAll('img').forEach(im=>{const hide=()=>{if(!im.dataset.fallback)im.style.display='none'};im.addEventListener('error',hide);if(im.complete&&!im.naturalWidth)hide()});const cards=[...d.querySelectorAll('.service-card[data-category]')];const search=d.querySelector('#search');const filters=[...d.querySelectorAll('.filter')];let category='all';const initial=new URLSearchParams(location.search).get('category');if(filters.some(b=>b.dataset.category===initial))category=initial;const apply=()=>{let q=(search?.value||'').trim().toLocaleLowerCase('ru');let count=0;cards.forEach(c=>{const show=(category==='all'||category===c.dataset.category)&&c.textContent.toLocaleLowerCase('ru').includes(q);c.hidden=!show;if(show){count++;c.classList.add('shown')}});filters.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)));const n=d.querySelector('#count');if(n)n.textContent='Найдено: '+count;const empty=d.querySelector('#empty');if(empty)empty.hidden=count!==0};if(cards.length){filters.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;apply()}));search?.addEventListener('input',apply);apply()}const form=d.querySelector('.booking-form');if(form){const service=new URLSearchParams(location.search).get('service');if(service){const opts=[...form.elements.service.options];if(opts.some(o=>o.value===service))form.elements.service.value=service}form.addEventListener('submit',e=>{e.preventDefault();const v=new FormData(form);const msg='Здравствуйте! Хочу записаться в GARMONIA.\nУслуга: '+v.get('service')+'\nИмя: '+v.get('name')+'\nТелефон: '+v.get('phone')+'\nУдобное время: '+(v.get('date')||'по согласованию');const u='https://wa.me/79295151055?text='+encodeURIComponent(msg);form.querySelector('output').textContent='Откроется WhatsApp с подготовленным сообщением. Отправьте его самостоятельно, чтобы согласовать запись.';window.open(u,'_blank','noopener,noreferrer')})}})();(()=>{if(!document.querySelector('.filters'))return;const themes={all:'laser',face:'lips',device:'laser',injection:'lips',body:'care',nails:'care',brows:'lips',epil:'laser'};const set=c=>{if(themes[c])document.body.dataset.beauty=themes[c]};set(new URLSearchParams(location.search).get('category')||'all');document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>set(b.dataset.category)))})();

/* Equalize incomplete rows without adding fake cards. */
(()=>{const grids=[...document.querySelectorAll('.grid')];function balance(){for(const g of grids){const all=[...g.children].filter(c=>c.matches('.category-card,.service-card,.review'));if(!all.length)continue;g.classList.add('balanced-grid');all.forEach(c=>c.classList.remove('tail-3-pair','tail-3-single','tail-2-single'));const visible=all.filter(c=>!c.hidden);const count=visible.length;if(!count)continue;if(count%3===1)visible[count-1].classList.add('tail-3-single');if(count%3===2)visible.slice(-2).forEach(c=>c.classList.add('tail-3-pair'));if(count%2===1)visible[count-1].classList.add('tail-2-single')}}balance();document.querySelector('#search')?.addEventListener('input',balance);document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',balance));
/* Keep portrait photographs intact, with a matching edge treatment. */
function styleImage(im){const p=im.closest('.photo');if(!p||!im.naturalWidth)return;const local=/^assets\/media\/|\/assets\/media\//.test(im.getAttribute('src')||'');p.classList.toggle('is-illustration',local);p.classList.toggle('is-portrait',!local&&im.naturalWidth/im.naturalHeight<.85);p.classList.add('has-picture');p.style.setProperty('--picture','url('+JSON.stringify(im.currentSrc||im.src)+')')}
document.querySelectorAll('.photo img').forEach(im=>{im.addEventListener('load',()=>styleImage(im));if(im.complete&&im.naturalWidth)styleImage(im)});
})();




